{
  "qid": "t2i_0010_001",
  "sample_id": "0010",
  "gen_prompt": "画面主体为北京传统食物咯吱盒，背景是春节庙会的年货托盘，旁边有一小碟椒盐和一双筷子。",
  "invocation": "L2",
  "knowledge_dim": "食物形态与质感（京味传统小吃）",
  "fidelity_checks": [
    {
      "check": "咯吱盒主体必须呈现为可辨识的小件形态：小块/不规则小片（归入块状）或小卷/卷段；不得是整张未切的大薄饼。",
      "anchor": {
        "type": "direct",
        "constraint_refs": ["1"],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "主体是整张未切的大薄饼、大饼、面条、丸子、饺子等，或完全没有可辨识的咯吱盒小件。",
        "tier_1": "可见部分小件，但同时有整张大薄饼/大饼，或小件形态模糊到无法确认是块状还是卷状。",
        "tier_2": "所有可辨识的咯吱盒主体均为小件：呈小块/不规则小片（归入块状）或小卷/卷段；没有整张未切的大薄饼。若远景无法分辨块/卷，只要可见尺寸比例像小件且无大饼，也判满分。"
      },
      "variants_used": "块状（含不规则小块/小片）或卷状/卷段均可",
      "visibility_requirement": "近景主体可见时判；若远景无法分辨块/卷，只要可见尺寸比例像小件且无整张大薄饼，视为满足；完全不可见则按主体缺失由 gate 处理。",
      "weight": 1.0
    },
    {
      "check": "咯吱盒外表必须呈油炸形成的金黄至黄褐色（深金黄）色泽。",
      "anchor": {
        "type": "direct",
        "constraint_refs": ["2"],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "主体外表呈白色/灰色/青绿色/焦黑/未加热色，或完全没有黄褐油炸色。",
        "tier_1": "外表大部分偏淡黄或黄褐不稳定，只有局部呈金黄至黄褐。",
        "tier_2": "主体外表整体呈金黄至黄褐色（深金黄），允许深浅不均和少量焦边，但主色明确为油炸黄褐。"
      },
      "variants_used": "无",
      "visibility_requirement": "当主体表面可见时判；若被完全遮挡，本条按可见表面判；完全不可见则按主体缺失由 gate 处理。",
      "weight": 1.0
    },
    {
      "check": "咯吱盒外皮必须呈油炸后的酥脆质感，表面干爽酥松，可见炸制气泡或酥层等特征。",
      "anchor": {
        "type": "direct",
        "constraint_refs": ["3"],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "表面湿滑、软塌、光滑无炸制纹理，或明显像蒸/煮/泡汤。",
        "tier_1": "表面较干但缺少可见炸制气泡/酥层/酥脆边缘，质感模糊。",
        "tier_2": "表面干爽酥松，可见至少一种炸制特征：气泡、微裂酥层、酥脆边缘或粗糙酥皮；正常油光不扣分，即使有椒盐附着也不显湿软。"
      },
      "variants_used": "无",
      "visibility_requirement": "当主体表面可见时判；若被椒盐/筷子局部遮挡，按可见表面判；完全不可见则按主体缺失由 gate 处理。",
      "weight": 1.0
    },
    {
      "check": "切面可见的饼体内部必须呈绿豆面特有的黄绿色至豆黄色调；不得为小麦白面的纯白色。",
      "anchor": {
        "type": "direct",
        "constraint_refs": ["4"],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "可见断面为纯白/灰白小麦面色调，或可见明显深色/彩色馅料夹层。",
        "tier_1": "可见断面偏黄但不够黄绿/豆黄，或仅极小局部可见且色调不确定。",
        "tier_2": "可见断面呈黄绿色至豆黄色调，不是纯白；若画面没有任何可见断面，本条视为满足。"
      },
      "variants_used": "无",
      "visibility_requirement": "有可见断面/切口时判；完全无断面时不扣分，视为满足。",
      "weight": 1.0
    },
    {
      "check": "咯吱盒不得呈现为浸泡在汤汁中或水煮、烩制等带汤湿软的形态。",
      "anchor": {
        "type": "direct",
        "constraint_refs": ["5"],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "咯吱盒浸泡在汤汁/水中，或表面/容器内有明显汤水反光、烩制湿软形态。",
        "tier_1": "有轻微湿痕/水汽或局部边缘软塌，但未形成浸泡；正常油光不视为湿软。",
        "tier_2": "可见范围内没有汤汁、水煮或烩制湿软形态；咯吱盒呈干爽小件。若托盘底部不可见，按可见食物表面判。"
      },
      "variants_used": "无",
      "visibility_requirement": "在可见食物与容器范围内判；若汤水完全不可见且食物表面干爽，视为满足。",
      "weight": 1.0
    },
    {
      "check": "咯吱盒不得呈现为包裹明显馅料（肉馅/菜馅/豆沙馅等）的带馅点心形态。",
      "anchor": {
        "type": "direct",
        "constraint_refs": ["6"],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "明显包裹肉馅/菜馅/豆沙馅等，呈饺子、馅饼、夹心点心等带馅形态。",
        "tier_1": "有疑似夹层或鼓胀但不明确，难以确认是否带馅。",
        "tier_2": "没有明显馅料；外形为均质小件，可见断面（若有）为饼体而非馅心。若完全无断面，按外形无夹馅鼓胀判。"
      },
      "variants_used": "无",
      "visibility_requirement": "在外形、断面和夹层可见范围内判；若完全无断面，按外形无夹馅鼓胀判。",
      "weight": 1.0
    }
  ],
  "alignment_checks": [
    {
      "check": "题面规定画面主体为北京传统食物咯吱盒。",
      "facet": "subject_prominence",
      "rubric": {
        "tier_0": "咯吱盒不是视觉主体，或主体被椒盐/筷子/托盘完全取代。",
        "tier_1": "咯吱盒可见但占比/清晰度不足，需要寻找才能确认。",
        "tier_2": "咯吱盒占据画面主导位置与视觉焦点，体量明显大于配件；若完全不可见则判 0 分。"
      }
    },
    {
      "check": "题面规定背景是春节庙会的年货托盘。",
      "facet": "real_world_scene",
      "rubric": {
        "tier_0": "无春节庙会/年货托盘元素，或场景完全无关。",
        "tier_1": "有托盘但春节庙会氛围不明确，或背景虚化到无法辨识。",
        "tier_2": "背景可辨识为春节庙会的年货托盘；即使虚化也能看出托盘与年货/摊位氛围。若完全不可见则判 0 分。"
      }
    },
    {
      "check": "题面规定旁边有一小碟椒盐和一双筷子。",
      "facet": "quantity",
      "rubric": {
        "tier_0": "缺少椒盐碟或筷子，或数量明显错误（多碟/多双）。",
        "tier_1": "有椒盐碟和筷子，但数量/规格不完全匹配（如一双筷子画成两根散筷、椒盐碟非一小碟）。",
        "tier_2": "可见一小碟椒盐和一双筷子（两根成对）；若被局部遮挡但可数出为一碟一双，视为满足。"
      }
    },
    {
      "check": "题面规定咯吱盒旁边有配件，配件与主体呈旁边关系。",
      "facet": "noncontact_interaction",
      "rubric": {
        "tier_0": "配件与主体关系错误（叠压遮挡主体、悬浮、嵌入食物）。",
        "tier_1": "配件在旁边但空间关系生硬（筷子穿入、碟子不合理）。",
        "tier_2": "椒盐碟和筷子自然摆放在咯吱盒旁边，不破坏主体形态；若因景别无法判断接触，按不穿模即满足。"
      }
    }
  ],
  "quality_facets": [
    "material_texture",
    "physical_logic",
    "edge_clarity",
    "resolution"
  ],
  "aesthetic_facets": [
    "composition",
    "color_harmony",
    "emotional_expression"
  ],
  "leak_check": {
    "对照表": [
      {
        "constraint_ref": "1",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "2",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "3",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "4",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "5",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "6",
        "题面中是否出现": "无"
      }
    ],
    "结论": "全为无"
  },
  "notes": "样本图中的深褐色夹层不作为判分依据；按清单[6]不得明显馅料。块状/卷状均合法；无断面时[4]按满足处理。"
}
